Translate("deDE", "felwood", {
	title = "Teufelswald",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Teufelswald ist ein sterbender Wald im Norden von {link:kalimdor}Kalimdor{/link}, zwischen {link:ashenvale}Eschental{/link} im Süden und dem Schnee von {link:winterspring}Winterspring{/link} im Nordosten. Seine Bäume sind schwarz und verdreht, seine Bäche fließen grün und faulig, und seine Luft riecht nach Fäulnis und Rauch. Einst war er der nördliche Ausläufer des großen Waldes der {link:night-elves}Nachtelfen{/link}. Heute ist er die Wunde, die die {link:burning-legion}Brennende Legion{/link} hinterließ, als sie aus der Welt vertrieben wurde. Die Tiere des Teufelswalds sind wahnsinnig, seine {link:furbolgs}Furbolgs{/link} wild, und in seinen Senken wandeln noch immer Dämonen. Doch einige Druiden harren in seinen südlichen Lichtungen aus, und sie haben ihn nicht aufgegeben.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Der Wald war seit unzähligen Zeitaltern eine Heimat der {link:night-elves}Nachtelfen{/link}. Ihre Mondbrunnen und Grabhügel liegen überall in ihm verstreut, und die weißen Steine der {link:ruins-of-constellas}Ruinen von Constellas{/link} stehen noch in seinen westlichen Lichtungen. Die Uralten, Treants, die die Kaldorei beschützten, hatten ihr Heim unter seinen Bäumen. Im {link:third-war}Dritten Krieg{/link} kam die Legion nach {link:kalimdor}Kalimdor{/link}. Der Schreckenslord {link:tichondrius}Tichondrius{/link} trug den Schädel von {link:gul-dan}Gul'dan{/link} in den Wald, ein Relikt, prall gefüllt mit dämonischer Macht, und durch ihn goss er Verderbnis in das Land. Höllenbestien fielen brennend vom Himmel und hinterließen Krater, die bis heute schwären. Als {link:illidan-stormrage}Illidan Stormrage{/link} die Macht des Schädels für sich nahm und den Schreckenslord erschlug, war der Schaden bereits angerichtet. Der Wald, der überlebte, war ein Wald der {link:fel-magic}Teufelsmagie{/link}, und die Leute begannen, ihn Teufelswald zu nennen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Der Teufelswald gehört niemandem, und viele Mächte ringen um ihn. Im Süden unterhalten die Druiden des {link:emerald-circle}Emerald Circle{/link} ein kleines Lager namens Smaragdrefugium, wo sie die Krankheit erforschen und nach ihrer Heilung suchen. Die {link:horde}Horde{/link} hält den {link:bloodvenom-post}Blutgiftposten{/link} im Westen, und die {link:alliance}Allianz{/link} unterhält einen Hippogryphenhorst auf der {link:talonbranch-glade}Nachtlaublichtung{/link} im Nordosten. Zwischen ihnen liegt der Feind. Die Hexenmeister des {link:shadow-council}Schattenrats{/link} haben {link:jaedenar}Jaedenar{/link} zum Sitz ihres Ordens gemacht, und dort feilschen sie mit Dämonen. Die {link:satyrs}Satyrn{/link} der Jadefeuer beschmutzen die alten Mondbrunnen. Die {link:furbolgs}Furbolgs{/link} der {link:deadwood-furbolgs}Totenwaldfelle{/link} sind wahnsinnig geworden. Im hohen Norden halten die {link:timbermaw-furbolgs}Holzschlund-Furbolgs{/link} den Pass nach {link:winterspring}Winterspring{/link} und trauen fast niemandem. Die Verderbnis bleibt nicht im Teufelswald: Die Druiden der {link:darkshore}Dunkelküste{/link} fürchten, dass sie nach Westen in ihre eigenen Wälder sickert.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Der {link:emerald-circle}Emerald Circle{/link}.{/b} Druiden des {link:cenarion-circle}Zirkels des Cenarius{/link}, aus der {link:alliance}Allianz{/link} wie aus der {link:horde}Horde{/link}, die geschworen haben, den Wald zu heilen.
• {b}Der {link:shadow-council}Schattenrat{/link}.{/b} Hexenmeister und Kultisten, die {link:jaedenar}Jaedenar{/link} mit Dämonen der Legion an ihrer Seite halten.
• {b}Die {link:satyrs}Satyrn{/link} der Jadefeuer.{/b} Sie spuken in den {link:ruins-of-constellas}Ruinen von Constellas{/link}, im {link:jadefire-glen}Jadefeuertal{/link} und am {link:jadefire-run}Jadefeuerbach{/link} und verbreiten Verderbnis, wohin sie auch gehen.
• {b}Die {link:deadwood-furbolgs}Totenwaldfelle{/link}.{/b} Ein Stamm, den die {link:fel-magic}Teufelsmagie{/link} in den Wahnsinn trieb, mit Dörfern im äußersten Süden und im äußersten Norden des Waldes.
• {b}Die {link:timbermaw-furbolgs}Holzschlund-Furbolgs{/link}.{/b} Der eine Stamm, der seinen Verstand bewahrt hat und die Tunnel der {link:timbermaw-hold}Holzschlundfeste{/link} bewacht.
• {b}Die verderbte Wildnis.{/b} Elementare des Wirrholzes, verseuchte Treants, Schlammwesen, rasende Bären, Wölfe und Eulenbestien sowie Höllenbestien, die noch immer durch das {link:shatter-scar-vale}Shatter Scar-Tal{/link} wandeln.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Wald der Kaldorei.{/b} Jahrtausendelang waren die nördlichen Wälder ein stilles Land der Mondbrunnen, Grabhügel und Uralten.
• {b}Der Dritte Krieg.{/b} Das Heer der Legion marschierte auf den {link:mount-hyjal}Berg Hyjal{/link}. {link:tichondrius}Tichondrius{/link} verdarb den Wald mit dem {link:skull-of-gul-dan}Schädel von Gul'dan{/link}, und Höllenbestien wurden auf ihn herabgerufen.
• {b}Illidans Wahl.{/b} {link:illidan-stormrage}Illidan Stormrage{/link} verzehrte den Schädel, nahm die Gestalt eines Dämons an und erschlug Tichondrius in diesen Wäldern. Sein Bruder verbannte ihn dafür.
• {b}Die Gegenwart.{/b} Das Heer der Legion wurde in der {link:battle-of-mount-hyjal}Schlacht um den Berg Hyjal{/link} gebrochen, doch der Teufelswald heilte nicht. Dämonen, {link:satyrs}Satyrn{/link} und Hexenmeister sind geblieben, und nur eine Handvoll Druiden stellt sich ihnen entgegen.]=],
		},
		{
			title = "Überlieferungen des Waldes",
			text = [=[• Die Druiden des {link:emerald-circle}Emerald Circle{/link} haben gelernt, eine Salbe herzustellen, die eine verderbte Pflanze wieder gesund macht. Liedblumen, Windblüten, Peitschenwurzeln und Nachtdrachenblüten, die man für verloren hielt, sind unter ihrer Pflege wieder erblüht.
• Eine Flöte, geschnitzt aus dem Holz eines gefallenen Uralten, fand man in den Händen eines Satyrs. Der Geist des Uralten war in ihr gebunden und fand keine Ruhe, bis die Wasser des {link:temple-of-the-moon}Tempels des Mondes{/link} ihn befreiten.
• Der {link:shadow-council}Schattenrat{/link} bewacht seine Festung mit vier Kohlenbecken, deren Namen Schmerz, Bosheit, Leid und Hass lauten.
• Die Geister dreier Uralter, {link:vartrus-the-ancient}Vartrus{/link}, Stoma und Hastat, antworten noch immer jenen, die zu einem bestimmten Felsen im Eisenwald kommen.]=],
		},
	},
})

Translate("deDE", "emerald-sanctuary", {
	title = "Das Smaragdrefugium",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Smaragdrefugium ist ein kleines Lager von Druiden im Süden des Teufelswalds, nahe der Grenze zu {link:ashenvale}Eschental{/link}. Es ist die Heimat des {link:emerald-circle}Emerald Circle{/link}. Hier arbeiten Druiden der {link:night-elves}Nachtelfen{/link} und der {link:tauren}Tauren{/link} Seite an Seite, was auch immer ihre Völker anderswo trennt. Sie sammeln Proben von allem Verseuchten, das der Wald hervorbringt, und suchen nach Mitteln, es zu reinigen. Freunde beider Seiten sind dort willkommen. Ringsum ist der Wald dunkel und feindselig, und {link:satyrs}Satyrn{/link} der Jadefeuer lauern im nahen Tal.]=],
		},
	},
})

Translate("deDE", "bloodvenom-post", {
	title = "Blutgiftposten",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Blutgiftposten ist der Stützpunkt der {link:horde}Horde{/link} im westlichen {link:felwood}Teufelswald{/link}, ein Lager aus Zelten und Palisaden am Rand der verderbten Wälder. {link:orcs}Orcs{/link} aus {link:orgrimmar}Orgrimmar{/link} und {link:forsaken}Verlassene{/link} aus {link:undercity}Undercity{/link} teilen sich seine Feuer. Es ist ein harter Posten in einem feindseligen Land. Seine Krieger haben gegen den {link:shadow-council}Schattenrat{/link} und die wahnsinnigen {link:furbolgs}Furbolgs{/link} des Waldes gekämpft, und manche sind nicht zurückgekehrt. Seine Agenten blicken weiter hinaus: Einer erforscht die verderbten Mondbrunnen der {link:satyrs}Satyrn{/link}, ein anderer die Wildekin von {link:winterspring}Winterspring{/link}. Ein Windreitermeister hält die Verbindung des Postens zum Rest der Horde.]=],
		},
	},
})

Translate("deDE", "talonbranch-glade", {
	title = "Nachtlaublichtung",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Nachtlaublichtung ist ein kleines Lager der {link:night-elves}Nachtelfen{/link} im nordöstlichen {link:felwood}Teufelswald{/link}. Hippogryphen nisten in ihren Bäumen und tragen Botschaften und Reisende zum Rest der {link:alliance}Allianz{/link}. Einige Kaldorei halten sie: ein Händler, ein Waffenschmied und die Lehrmeister, die Druiden und Jäger für den langen Krieg gegen die Verderbnis ausbilden. Sie ist ein Ort der Rast vor der Straße nach Norden und einer der letzten Außenposten der Nachtelfen in dem Wald, der einst ganz ihnen gehörte.]=],
		},
	},
})

Translate("deDE", "jaedenar", {
	title = "Jaedenar",
	aliases = { "Schattenfeste" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Jaedenar liegt im westlichen {link:felwood}Teufelswald{/link}, einen Pfad von der Hauptstraße hinab. Es war einst ein Ort der {link:night-elves}Nachtelfen{/link}, mit einem Mondbrunnen in seinem Herzen und Grabhügeln darunter. Heute ist es der Sitz des {link:shadow-council}Schattenrats{/link}. Kultisten, Hexenmeister und ihre Hunde halten die Oberfläche, und der Mondbrunnen ist faulig geworden. Darunter liegt die Schattenfeste, die Festung des Rates, in der Dämonen der Legion offen umhergehen. Ihre Kammern werden von vier Kohlenbecken des Schutzes bewacht. An ihrem tiefsten Punkt hält ein Schreckenslord Hof, und die Hexenmeister, die ihm dienen, schließen im Dunkeln ihre Pakte.]=],
		},
	},
})

Translate("deDE", "irontree-woods", {
	title = "Der Eisenwald",
	aliases = { "Eisenstammhöhle" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Eisenwald ist das nördliche Herz des Teufelswalds, ein Landstrich verseuchter Bäume und Ruinen. Einst wandelten hier Treants als Hüter des Waldes. Die Verderbnis verdrehte sie, und die, die geblieben sind, wandern und stampfen zwischen den toten Bäumen umher. In der Eisenstammhöhle sind die Elementare des Wirrholzes so tief gesunken, dass die Druiden nicht mehr hoffen, sie zu reinigen. Doch der Wald ist nicht ganz verloren. In den Ruinen seines südlichen Teils verweilt der Geist einer Uralten namens {link:arei}Arei{/link}, und die Geister dreier weiterer Uralter antworten noch immer an einem Stein zwischen den Bäumen.]=],
		},
	},
})

Translate("deDE", "shatter-scar-vale", {
	title = "Shatter Scar-Tal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Shatter Scar-Tal liegt östlich der Straße im mittleren {link:felwood}Teufelswald{/link}. Im {link:third-war}Dritten Krieg{/link} rief die Legion ihre Höllenbestien auf dieses Tal herab, und die Krater, die sie schlugen, zeichnen noch immer den Boden. Fauliges grünes Wasser sammelte sich in den Gruben und ist nie klar geworden. Höllenbestien wandeln noch immer zwischen ihnen, hirnlos und zerstörerisch, mit Elementaren reiner Entropie an ihrer Seite. Die Druiden hatten gehofft, eine saubere Quelle im Teufelswald zu finden. Hier fanden sie sie nicht. Irgendwo im Tal liegen die ausgebrannten Überreste der Höllenbestie {link:kroshius}Kroshius{/link}.]=],
		},
	},
})

Translate("deDE", "ruins-of-constellas", {
	title = "Ruinen von Constellas",
	aliases = { "Constellas" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Ruinen von Constellas liegen im südwestlichen {link:felwood}Teufelswald{/link}. Sie waren eine Stadt der {link:night-elves}Nachtelfen{/link}, und in ihrem Herzen steht ein Mondbrunnen, der einst ein Sinnbild der Erneuerung war. Die {link:satyrs}Satyrn{/link} der Jadefeuer haben die Ruinen zu ihrer Heimat gemacht, und der Mondbrunnen ist nun randvoll mit Verderbnis. Sein Wasser dient dazu, weitere Satyrn hervorzubringen, und ein Tier, das daraus trinkt, wird größer und stärker und durch und durch abscheulich. Der Satyr {link:xavathras}Xavathras{/link} herrschte hier, und sein Werk nährte die Pläne eines anderen Satyrs im Norden.]=],
		},
	},
})

Translate("deDE", "jadefire-glen", {
	title = "Jadefeuertal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Jadefeuertal ist eine dunkle Senke im südlichen {link:felwood}Teufelswald{/link}, nahe dem Smaragdrefugium. Es trägt seinen Namen nach den {link:satyrs}Satyrn{/link} der Jadefeuer, die es halten. Ihre Teufelsverschworenen und Schurken sammeln sich hier, um Verderbnis unter die Tiere des südlichen Waldes zu tragen. Die Druiden des Refugiums leben mit den Satyrn fast vor ihrer Tür, und sie zählen {link:stranglethorn-vale}das Tal{/link} zu den ersten Orten, die gereinigt werden müssen, wenn der Wald je heilen soll.]=],
		},
	},
})

Translate("deDE", "jadefire-run", {
	title = "Jadefeuerbach",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Jadefeuerbach liegt im Nordwesten des Teufelswalds. Er ist das zweite Lager der {link:satyrs}Satyrn{/link} der Jadefeuer, und das gefährlichere. Höllenrufer, Verräter und Gaukler sammeln sich hier unter dem Satyr {link:xavaric}Xavaric{/link}, der die Früchte des verderbten Mondbrunnens von {link:ruins-of-constellas}Constellas{/link} empfing. Die Satyrn am Bach nähren sich von der Verderbnis der Geschöpfe des Waldes. Unter ihnen fand man eine hölzerne Flöte, geschnitzt aus einem gefallenen Uralten, und sie verriet den Druiden, dass die Grausamkeit der Satyrn selbst die Beschützer des Waldes erreichte.]=],
		},
	},
})

Translate("deDE", "deadwood-village", {
	title = "Lager der Totenwaldfelle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Lager der Totenwaldfelle ist ein Furbolgdorf im äußersten Süden des Teufelswalds, nahe der Grenze zu {link:ashenvale}Eschental{/link}. Es gehört dem {link:deadwood-furbolgs}Stamm der Totenwaldfelle{/link}, den die {link:fel-magic}Teufelsmagie{/link} in den Wahnsinn getrieben hat. Krieger, Pfadfinder und Gärtner bewachen seine Hütten, und ihr {link:overlord-ror}Oberherr Ror{/link} ist ein großer, besudelter {link:furbolgs}Furbolg{/link} von schrecklicher Kraft. Der {link:timbermaw-furbolgs}Holzschlund{/link}-Furbolg {link:grazle}Grazle{/link} beobachtet das Dorf aus der Nähe und bittet jene, die Freunde seines Stammes werden wollen, ihre Zahl zu verringern.]=],
		},
	},
})

Translate("deDE", "felpaw-village", {
	title = "Revier der Teufelspfoten",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Revier der Teufelspfoten ist das nördliche {link:deadwood-village}Lager der Totenwaldfelle{/link}, in den Hügeln unterhalb des Eingangs zur {link:timbermaw-hold}Holzschlundfeste{/link}. Höhlenwächter, Rächer und Schamanen leben hier unter Häuptling Bloodmaw. Die {link:timbermaw-furbolgs}Holzschlund{/link}, die die Feste bewachen, blicken voller Kummer auf das Lager hinab, denn seine Bewohner sind ihre eigenen Brüder. In dem Lager steht ein Kessel mit einem grünen, stinkenden Gebräu. Man hat {link:furbolgs}Furbolgs{/link} der {link:winterfall-furbolgs}Winterfelle{/link} aus dem Schnee dahinter durch die Feste ziehen sehen, und manche vermuten, dass das Gebräu zu ihnen nach Norden getragen wird.]=],
		},
	},
})

Translate("deDE", "timbermaw-hold", {
	title = "Holzschlundfeste",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Holzschlundfeste ist die Heimat der {link:timbermaw-furbolgs}Holzschlund-Furbolgs{/link}, ein Netz von Tunneln in den Bergen am Nordrand des Teufelswalds. Ihre Gänge führen durch den Fels nach {link:winterspring}Winterspring{/link} und sind die einzige Straße nach Norden. Die {link:furbolgs}Furbolgs{/link} bewachen sie erbittert. Fremde, die ihr Vertrauen nicht verdient haben, werden mit Speeren empfangen, und wer einen Holzschlund tötet, selbst zur Verteidigung, gilt als ihr Feind. Drinnen halten ihre Ältesten, Mystiker und Händler das Leben des Stammes in Gang, und sie erforschen die Verderbnis, die ihre Verwandten ergriffen hat.]=],
		},
	},
})

Translate("deDE", "eridan-bluewind", {
	title = "Eridan Bluewind",
	subtitle = "Druidin des Emerald Circle",
	found = "Das Smaragdrefugium, im südlichen Teufelswald",
	hint = [=[Sucht die Druidin des Emerald Circle, die das Leiden der Uralten spüren kann.]=],
	allegiance = "Emerald Circle · Zirkel des Cenarius",
	aliases = { "Eridan" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Eridan Bluewind ist eine Druidin des {link:emerald-circle}Emerald Circle{/link}, die im Smaragdrefugium lebt. Sie hat sich der Heilung des Teufelswalds verschrieben, und sie trägt seinen Schmerz mit sich. Ein großer Teil ihrer Arbeit ist Krieg. Sie schickt Verbündete gegen die {link:satyrs}Satyrn{/link} der Jadefeuer, die die Verderbnis verbreiten, und sie setzt ihre eigene Kraft ein, um ungeschehen zu machen, was diese angerichtet haben.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Eridan erkannte als Erste des {link:emerald-circle}Emerald Circle{/link}, dass die {link:satyrs}Satyrn{/link} des Teufelswalds nicht einfach grausam, sondern organisiert waren. Das Lager des {link:xavathras}Xavathras{/link} im Süden, so erfuhr sie, pflegte einen verderbten Mondbrunnen zum Nutzen Xavarics im Norden. Sie vermutet, dass noch etwas Größeres hinter ihnen steht. Ihr Wissen reicht auch weit über den {link:felwood}Teufelswald{/link} hinaus: Reisende suchen sie wegen Geheimnissen der {link:elements}Elemente{/link} auf, die nur wenige andere kennen.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie schickte Kämpfer gegen {link:xavathras}Xavathras{/link} in den {link:ruins-of-constellas}Ruinen von Constellas{/link} und gegen {link:xavaric}Xavaric{/link} am {link:jadefire-run}Jadefeuerbach{/link}.
• Sie befreite den Geist eines Uralten, den die {link:satyrs}Satyrn{/link} in einer Flöte gebunden hatten.
• Sie lehrte die Herstellung eines Totems, das die Aura des Feuerelementars {link:blazerunner}Blazerunner{/link} im {link:un-goro-crater}Un'Goro-Krater{/link} brechen kann.]=],
		},
	},
	chapters = {
		{
			title = "Die Jadefeuer",
			hint = "Streckt die Satyrfürsten der Jadefeuer nieder.",
			text = [=[Als {link:xavathras}Xavathras{/link} fiel, jubelte Eridan nicht. Sie hatte gespürt, dass der {link:satyrs}Satyr{/link} nur ein Teil eines größeren Plans war. Die Wahrheit kam langsam: Xavathras hatte einen verderbten Mondbrunnen gepflegt und dessen Beute nach Norden zu {link:xavaric}Xavaric{/link} gebracht. Als beide erschlagen waren, betete sie, dass Elune jene beschützen möge, die das Werk getan hatten. Die Heilung, das wusste sie, würde weit länger dauern als das Töten.]=],
		},
		{
			title = "Der gebundene Uralte",
			hint = [=[Bringt der Druidin die Flöte, die man bei einem Satyr fand, und das gesegnete Wasser des Tempels des Mondes.]=],
			text = [=[Die Flöte Xavarics war aus einem der Uralten geschnitzt worden, jener Treants, die die {link:night-elves}Nachtelfen{/link} beschützten. Durch {link:fel-magic}Teufelsmagie{/link} war der Geist des Uralten an das Holz gebunden und dort gequält worden. Eridan konnte es kaum ertragen, sie zu halten. Sie wusch sie im gesegneten Wasser Elunes, und die Verbindung zerbrach. Sie glaubte, dass die Flöte, an einem heiligen Ort gespielt, die Geister von Uralten rufen könnte, die noch immer im Wald umgehen.]=],
		},
		{
			title = "Der Auftrag eines Fremden",
			hint = [=[Kommt im Namen eines Wanderers aus dem Un'Goro-Krater zu Eridan.]=],
			text = [=[Ein Fremder im {link:un-goro-crater}Un'Goro-Krater{/link} hatte ihren Namen genannt, als er sich an kaum etwas anderes erinnern konnte. Eridan kannte ihn nicht, aber sie kannte sein Anliegen. Sie sammelte Klauen und das Herz eines Treants aus dem Eisenwald und schickte sie mit dem Buch von Aquor zu einem Steinkreis in {link:tanaris}Tanaris{/link}, wo der Wasserelementar Aquementas gerufen werden konnte, um sie zu einem Totem zu schmieden.]=],
		},
	},
	mentions = {
		{ text = "Die Flöte des {link:xavaric}Xavaric{/link}" },
		{ text = "Linkens Erinnerung" },
		{ text = "Silbernes Herz" },
		{ text = "Aquementas" },
		{ text = "Die Verderbnis der Jadefeuer" },
		{ text = "Teufelsgebundene Uralte" },
		{ text = "Gereinigt!" },
		{ text = "Weitere Verderbnis" },
	},
	bonds = {
		{ id = "xavathras", name = "Xavathras", note = "der Satyr, den sie erschlagen ließ" },
		{ id = "xavaric", name = "Xavaric", note = "der Satyrfürst des Nordens" },
		{ id = "arei", name = "Arei", note = "ein uralter Geist des Waldes" },
		{ id = "greta-mosshoof", name = "Greta Mosshoof", note = "aus demselben Zirkel" },
	},
})

Translate("deDE", "greta-mosshoof", {
	title = "Greta Mosshoof",
	subtitle = "Druidin des Emerald Circle",
	found = "Das Smaragdrefugium, im südlichen Teufelswald",
	hint = [=[Sucht die Druidin des Emerald Circle, die Krieg gegen den Schattenrat führt.]=],
	allegiance = "Emerald Circle · Zirkel des Cenarius",
	aliases = { "Greta" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Greta Mosshoof ist eine Druidin des {link:emerald-circle}Emerald Circle{/link}, und sie betet zur Erdmutter. Wo andere ihres Zirkels den Wald zu heilen suchen, hat sie die Aufgabe übernommen, die Ursache seiner Krankheit anzugreifen. Ihr Feind ist der {link:shadow-council}Schattenrat{/link} in {link:jaedenar}Jaedenar{/link}, und sie will ihm den Kopf abschlagen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Greta ist die Planerin des Krieges des Zirkels gegen {link:jaedenar}Jaedenar{/link}. Sie versteht, dass man den Rat nicht blind bekämpfen kann, und sie ist geduldig genug, erst zu lernen, bevor sie zuschlägt. Sie ist auch die Hüterin einer größeren Hoffnung: der Suche nach einem Heilmittel, das eines Tages die Bäume und Geschöpfe des Teufelswalds heilen könnte.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie prüfte die Entschlossenheit jener, die ihr gegen die Kultisten von {link:jaedenar}Jaedenar{/link} helfen wollten.
• Sie ließ das verderbte Wasser des Mondbrunnens von Jaedenar von den Geistern des Wassers reinigen.
• Sie spähte in die Schattenfeste und erfuhr, wer den Rat anführte.
• Sie schickte ihre Verbündeten gegen {link:shadow-lord-fel-dan}Schattenfürst Fel'dan{/link} und seine Diener.
• Sie suchte das Blut des grünen Drachen {link:morphaz}Morphaz{/link} für das zweite Heilmittel des Teufelswalds.]=],
		},
	},
	chapters = {
		{
			title = "Wasser gegen Feuer",
			hint = [=[Lasst das Wasser des Mondbrunnens von Jaedenar reinigen und nutzt es an den Kohlenbecken der Schattenfeste.]=],
			text = [=[Der Rat schirmte die {link:jaedenar}Schattenfeste{/link} mit Zaubern ab, die in vier Kohlenbecken brannten. Greta ließ Wasser aus dem verderbten Mondbrunnen im Herzen Jaedenars holen und schickte es dann nach Süden zu einer alten Freundin, einer Schamanin, die am Meer südlich von {link:ratchet}Ratchet{/link} lebt. Die Geister des Wassers erhörten die Schamanin und segneten die Sache. Mit dem gereinigten Wasser wurden die Flammen gelöscht. Für kurze Zeit, bevor die Hexenmeister ihre Schutzzauber erneuerten, konnte Greta in die Feste blicken.]=],
		},
		{
			title = "Der Kopf der Schlange",
			hint = [=[Schlagt gegen den Sterblichen zu, der den Schattenrat anführt.]=],
			text = [=[Was Greta sah, sagte ihr, dass es keinen listigen Weg hinein gab. {link:shadow-lord-fel-dan}Fel'dan{/link}, der Schattenfürst, war der Sterbliche, der unten befahl, und er war es, der die Pakte mit der Legion schloss. Sie schickte ihre Verbündeten geradewegs zu ihm hinab. Als sein Kopf zu ihr zurückkam, pries sie die Erdmutter. Sie hoffte, dass {link:shadow-council}der Rat{/link} sich ohne ihn gegen sich selbst wenden würde.]=],
		},
		{
			title = "Das zweite Heilmittel",
			hint = [=[Bringt ihr das Blut des Drachen Morphaz aus dem versunkenen Tempel.]=],
			text = [=[Man sagt, der grüne Drache {link:morphaz}Morphaz{/link} sei gegen jedes Gift und jede Krankheit gefeit, und viele Druiden starben, um das zu erfahren. Greta wollte sein Blut. Als es kam, konnte sie es kaum glauben. Es werde ein Leben lang dauern, sagte sie, ungeschehen zu machen, was im {link:felwood}Teufelswald{/link} geschehen war, doch endlich habe der Zirkel die Mittel, damit zu beginnen.]=],
		},
	},
	mentions = {
		{ text = "Die Streitkräfte von {link:jaedenar}Jaedenar{/link}" },
		{ text = "Sammeln des verderbten Wassers" },
		{ text = "Die Suche nach spiritueller Hilfe" },
		{
			text = [=[Gereinigtes Wasser kehrt in den {link:felwood}Teufelswald{/link} zurück]=],
		},
		{ text = "Die Flammen des Schutzes löschen" },
		{ text = "Ein letzter Schlag" },
		{ text = "Blut des {link:morphaz}Morphaz{/link}" },
	},
	bonds = {
		{ id = "shadow-lord-fel-dan", name = "Schattenfürst Fel'dan", note = "der Kopf der Schlange" },
		{ id = "eridan-bluewind", name = "Eridan Bluewind", note = "aus demselben Zirkel" },
		{ id = "morphaz", name = "Morphaz", note = "dessen Blut sie suchte" },
	},
})

Translate("deDE", "lord-banehollow", {
	title = "Lord Banehollow",
	subtitle = "Schreckenslord von Jaedenar",
	found = "Die Tiefen der Schattenfeste, in Jaedenar",
	hint = [=[Hüllt Euch in Schatten und sucht den Schreckenslord am Grund von Jaedenar auf.]=],
	allegiance = "Brennende Legion · Schattenrat",
	aliases = { "Banehollow" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lord Banehollow ist ein Schreckenslord, der in den Tiefen von {link:jaedenar}Jaedenar{/link} Hof hält, dem Sitz des {link:shadow-council}Schattenrats{/link}. Er ist alt, geduldig und grausam. Die Hexenmeister des Rates kommen und gehen vor ihm, und nur wer den Schatten des Rates selbst trägt, darf sich ihm unversehrt nähern.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Banehollow ist der Dämon hinter den sterblichen Hexenmeistern von {link:jaedenar}Jaedenar{/link}, und er hat Rivalen selbst unter seinesgleichen. Der wichtigste unter ihnen ist Lord Hel'nurath, der über ein Reich namens Xoroth jenseits dieser Welt herrscht und dort die berühmten Schreckensrösser züchtet. Banehollow hütet einen Vorrat an Sternenstaub aus Xoroth, und Hexenmeister, die einen Weg in jenes Reich öffnen wollen, müssen mit ihm darum feilschen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er herrscht aus den Tiefen der {link:jaedenar}Schattenfeste{/link}.
• Er entlarvte seinen Diener {link:ulathek}Ulathek{/link} als Spion Hel'naruths.
• Er verkauft den Sternenstaub von Xoroth über seinen Diener Ur'dan.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik verzeichnet, wie lange Banehollow schon im {link:felwood}Teufelswald{/link} weilt oder welcher Handel ihn an den {link:shadow-council}Schattenrat{/link} bindet.]=],
		},
	},
	chapters = {
		{
			title = "Ein Gast in Jaedenar",
			hint = [=[Kommt nach Jaedenar, getarnt durch die schattenhaften Tränke der Brennenden Steppe.]=],
			text = [=[Der Goblin {link:gorzeeki-wildeyes}Gorzeeki Wildeyes{/link} braut Tränke, die ihren Trinker als einen des Schattenrats durchgehen lassen. Wer sie trinkt, kann durch {link:jaedenar}Jaedenar{/link} gehen und vor Banehollow treten. Er heißt sie nicht herzlich willkommen. Seine Geduld, sagt er, umspannt Jahrtausende, und dennoch dürfen sie nicht mehr als einen Augenblick davon haben.]=],
		},
		{
			title = "Das Herz des Verräters",
			hint = "Beweist dem Schreckenslord Eure Dienste.",
			text = [=[{link:ulathek}Ulathek{/link} kroch vor seinem Meister, während er mit Hel'nurath Ränke schmiedete, der hoffte, Banehollows Macht im {link:felwood}Teufelswald{/link} an sich zu reißen. Banehollow wusste es. Er wollte, dass man es Ulathek sagte, und er wollte die Angst sehen. Dann wollte er das Herz, das er eine Woche verrotten lassen wollte, bevor er es aß.]=],
		},
		{
			title = "Sternenstaub von Xoroth",
			hint = [=[Kauft den Sternenstaub von Xoroth vom Diener des Schreckenslords.]=],
			text = [=[Banehollow erriet sofort, warum ein Hexenmeister Sternenstaub wollte: um ein Portal in das Reich seines Rivalen zu öffnen und eines seiner Schreckensrösser zu stehlen. Der Gedanke störte ihn nicht. Er ließ seinen Diener Ur'dan den Sternenstaub verkaufen, gegen einen Preis. Er ging zurück zu {link:gorzeeki-wildeyes}Gorzeeki{/link} und von ihm zu {link:mor-zul-bloodbringer}Mor'zul Bloodbringer{/link}, der ihn für seine Tinte brauchte.]=],
		},
	},
	mentions = {
		{ text = "Lord Banehollow" },
		{ text = "{link:ulathek}Ulathek{/link} der Verräter" },
		{ text = "Xorothianischer Sternenstaub" },
	},
	bonds = {
		{ id = "ulathek", name = "Ulathek", note = "sein verräterischer Diener" },
		{ id = "gorzeeki-wildeyes", name = "Gorzeeki Wildeyes", note = "schickt ihm Besucher" },
		{ id = "mor-zul-bloodbringer", name = "Mor'zul Bloodbringer", note = "erhält seinen Sternenstaub" },
		{ id = "shadow-lord-fel-dan", name = "Schattenfürst Fel'dan", note = "der sterbliche Herr des Rates unter ihm" },
	},
})

Translate("deDE", "tichondrius", {
	title = "Tichondrius",
	subtitle = "Schreckenslord der Brennenden Legion",
	hint = [=[Erfahrt, wer den nördlichen Wald mit dem Schädel von Gul'dan vergiftete.]=],
	allegiance = "Brennende Legion",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tichondrius war ein Schreckenslord, einer der Nathrezim, die der {link:burning-legion}Brennenden Legion{/link} dienen. Im {link:third-war}Dritten Krieg{/link} gehörte er zu den Dämonen, die die {link:scourge}Geißel{/link} im Namen der Legion lenkten, und er gab dem Todesritter {link:arthas-menethil}Arthas Menethil{/link} seine Befehle. Als die Legion nach {link:kalimdor}Kalimdor{/link} kam, trug er den Schädel von {link:gul-dan}Gul'dan{/link} in den nördlichen Wald und vergiftete ihn mit der dunklen Macht des Schädels. Dieser Wald ist der {link:felwood}Teufelswald{/link}. Er wurde dort von {link:illidan-stormrage}Illidan Stormrage{/link} erschlagen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Von allen Dämonen des Dritten Krieges hinterließ Tichondrius das tiefste Mal im Land selbst. {link:archimonde}Archimonde{/link} fiel am {link:mount-hyjal}Berg Hyjal{/link}, und sein Heer wurde gebrochen, doch die Verderbnis, die Tichondrius säte, starb nicht mit ihm. Jeder wahnsinnige {link:furbolgs}Furbolg{/link}, jeder verseuchte Treant und jeder faulige Mondbrunnen im {link:felwood}Teufelswald{/link} ist Teil seines Erbes. Sein Tod veränderte auch {link:illidan-stormrage}Illidan{/link} für immer: Um ihn zu besiegen, nahm Illidan die Macht des Schädels in sich auf, und sein Volk verbannte ihn dafür.]=],
		},
		{
			title = "Die Geißel und die Legion",
			text = [=[Der Lichkönig schuf die {link:scourge}Geißel{/link}, doch er schuf sie nicht frei. Die Schreckenslords der Legion wachten über sie, und Tichondrius war unter ihnen. Nachdem {link:arthas-menethil}Arthas{/link} seinen Vater erschlagen und sich ganz der Geißel hingegeben hatte, prüfte Tichondrius die Treue des Prinzen und gab ihm seine Aufgaben. Arthas trug die Überreste des Nekromanten {link:kel-thuzad}Kel'Thuzad{/link} zum Sonnenbrunnen von {link:quel-thalas}Quel'Thalas{/link}, wo Kel'Thuzad als Lich auferweckt wurde. Kel'Thuzad wiederum rief {link:archimonde}Archimonde{/link} in {link:dalaran}Dalaran{/link} in die Welt. Da der Herr der Legion endlich gekommen war, hatte die Geißel ihren Zweck erfüllt, und die Dämonen wandten sich {link:kalimdor}Kalimdor{/link} zu.]=],
		},
		{
			title = "Die Vergiftung des Waldes",
			text = [=[Archimondes Heer marschierte auf den {link:mount-hyjal}Berg Hyjal{/link} und den Weltenbaum {link:nordrassil}Nordrassil{/link}. Tichondrius kam mit dem {link:skull-of-gul-dan}Schädel von Gul'dan{/link} in die nördlichen Wälder, den Überresten des Hexenmeisters, der die {link:orcs}Orcs{/link} einst als Erster an die Legion gebunden hatte. Der Schädel barg noch viel von Gul'dans Teufelsmacht, und Tichondrius nutzte sie, um die Wälder um sich herum zu verderben. Die Bäume wurden schwarz, und die Wasser verdarben. Tiere und {link:furbolgs}Furbolgs{/link} wurden wahnsinnig. Höllenbestien fielen brennend vom Himmel, und die Uralten, die den Wald beschützten, wurden vernichtet.]=],
		},
		{
			title = "Der Tod des Schreckenslords",
			text = [=[{link:tyrande-whisperwind}Tyrande Whisperwind{/link} hatte {link:illidan-stormrage}Illidan{/link} aus seiner langen Gefangenschaft befreit, damit er gegen die Dämonen kämpfte. Illidan erfuhr von dem Schädel und machte sich auf, ihn zu holen. Er nahm ihn und verzehrte seine Macht. Sie verwandelte ihn: Ihm wuchsen Hörner und große dunkle Schwingen, und er wurde selbst zum Teil ein Dämon. Mit dieser Macht erschlug er Tichondrius. Der Sieg kostete ihn alles andere. {link:malfurion-stormrage}Malfurion Stormrage{/link} konnte nicht verzeihen, was aus seinem Bruder geworden war, und er verbannte Illidan aus den Wäldern der {link:night-elves}Nachtelfen{/link}.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik erzählt, wie Tichondrius an den Schädel kam oder wie lange er im Wald weilte, bevor {link:illidan-stormrage}Illidan{/link} ihn fand.]=],
		},
	},
	chapters = {
		{
			title = "Die Erinnerung der Uralten",
			hint = "Führt den Geist einer Uralten aus dem verderbten Wald.",
			text = [=[Der uralte Geist {link:arei}Arei{/link} erinnert sich noch an den Wald, wie er war, bevor die Legion kam. Sie erinnert sich an die Höllenbestien, die Zerstörung und das Chaos. Sie erinnert sich, dass der {link:skull-of-gul-dan}Schädel von Gul'dan{/link} dafür sorgte, dass nichts im Wald verschont blieb. Selbst als Geist kann sie dem Leiden des Landes nicht entkommen. Sie bittet nur darum, hinausgeführt zu werden, damit sie ruhen kann.]=],
		},
	},
	mentions = {
		{ text = "Uralter Geist" },
	},
	bonds = {
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "sein Bezwinger" },
		{ id = "gul-dan", name = "Gul'dan", note = "der Hexenmeister, dessen Schädel er benutzte" },
		{ id = "archimonde", name = "Archimonde", note = "sein Meister im Dritten Krieg" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "der Todesritter, dem er befahl" },
		{ id = "arei", name = "Arei", note = "eine Uralte, die sich an seine Verderbnis erinnert" },
	},
})

Translate("deDE", "skull-of-gul-dan", {
	title = "Schädel von Gul'dan",
	aliases = { "Schädel Gul'dans" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Schädel von Gul'dan war der Schädel des orcischen Hexenmeisters {link:gul-dan}Gul'dan{/link}, des Gründers des {link:shadow-council}Schattenrats{/link}. Er überdauerte den Tod des Hexenmeisters im {link:the-sepulcher}Grabmal{/link} des {link:sargeras}Sargeras{/link} und bewahrte viel von seiner Teufelsmacht. Im {link:third-war}Dritten Krieg{/link} brachte der Schreckenslord {link:tichondrius}Tichondrius{/link} ihn nach {link:kalimdor}Kalimdor{/link} und nutzte ihn, um den nördlichen Wald zu verderben. {link:illidan-stormrage}Illidan Stormrage{/link} nahm ihn ihm ab und verzehrte seine Macht, und dadurch wurde er zu einem Wesen, halb Dämon.]=],
		},
		{
			title = "Sein Erbe",
			text = [=[Den Schädel gibt es nicht mehr, doch sein Werk bleibt. Der Wald, den er vergiftete, heißt {link:felwood}Teufelswald{/link}. Die Geister der Uralten erinnern sich, dass er nichts verschonte, und die Druiden des {link:emerald-circle}Emerald Circle{/link} kämpfen noch immer gegen das, was er hinterließ.]=],
		},
	},
})

Translate("deDE", "shadow-council", {
	title = "Schattenrat",
	aliases = { "der Rat" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Schattenrat ist ein geheimer Orden von Hexenmeistern, die der {link:burning-legion}Brennenden Legion{/link} dienen. Er entstand unter den {link:orcs}Orcs{/link} von Draenor und überlebte die {link:horde}Horde{/link}, die er einst beherrschte. Heute ist sein Sitz {link:jaedenar}Jaedenar{/link} im {link:felwood}Teufelswald{/link}, und seine Sekten sind über die ganze Welt verstreut.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Der Dämonenfürst {link:kil-jaeden}Kil'jaeden{/link} erwählte den Hexenmeister {link:gul-dan}Gul'dan{/link} zu seinem Diener unter den {link:orcs}Orcs{/link}. Gul'dan versammelte die ehrgeizigsten seiner Mithexenmeister in einem verborgenen Rat. Er beherrschte die Orcclans hinter einem Marionetten-Kriegshäuptling und brachte sie dazu, das Blut von {link:mannoroth}Mannoroth{/link} zu trinken. Durch Gul'dan öffnete er das {link:dark-portal}Dunkle Portal{/link}.]=],
		},
		{
			title = "Der Fall",
			text = [=[In den Tagen nach dem {link:first-war}Ersten Krieg{/link} machte der Rat die {red:blackrock-spire}Blackrockspitze{/red} zu seinem Sitz. {link:orgrim-doomhammer}Orgrim Doomhammer{/link} wandte sich dort gegen ihn, erschlug die meisten seiner Mitglieder und nahm {link:gul-dan}Gul'dan{/link} gefangen. Gul'dan verriet später die {link:horde}Horde{/link} und starb. Man glaubte, der Rat sei mit ihm gestorben.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Das war er nicht. In {link:jaedenar}Jaedenar{/link} führt {link:shadow-lord-fel-dan}Schattenfürst Fel'dan{/link} den Orden und schließt seine Pakte mit der Legion, während ein Schreckenslord in den Tiefen darunter Hof hält. Man gibt dem Rat die Schuld an vielen Übeln im {link:felwood}Teufelswald{/link} und anderswo. Sein Zeichen zeigt sich unter den Hexenmeistern des {link:arathi-highlands}Arathihochlands{/link}. In {link:orgrimmar}Orgrimmar{/link} dienen die {link:burning-blade}Burning Blade{/link} und die Searing Blade seinen Zwecken, und die Shadowsworn der {link:blasted-lands}Verwüsteten Lande{/link} sind seine Erben. {link:thrall}Thrall{/link} weiß, dass er lebt, und er will ihn finden.]=],
		},
	},
})

Translate("deDE", "emerald-circle", {
	title = "Emerald Circle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Emerald Circle ist eine Gemeinschaft von Druiden des {link:cenarion-circle}Zirkels des Cenarius{/link}, die sich dem {link:felwood}Teufelswald{/link} verschrieben haben. {link:night-elves}Nachtelfen{/link} und {link:tauren}Tauren{/link} dienen in ihm gemeinsam, und sie heißen Freunde der {link:alliance}Allianz{/link} wie der {link:horde}Horde{/link} willkommen. Vom Smaragdrefugium aus erforschen sie die Verderbnis und versuchen, sie umzukehren.]=],
		},
		{
			title = "Ihr Werk",
			text = [=[• Sie bekämpfen die {link:satyrs}Satyrn{/link} der Jadefeuer und den {link:shadow-council}Schattenrat{/link}, die die Verderbnis verbreiten und nähren.
• Sie haben gelernt, Salben herzustellen, die verderbte Pflanzen heilen, doch sie teilen dieses Wissen nur mit jenen, die sich bewähren.
• Sie suchen nach sauberem Wasser und nach einem Heilmittel, das die Bäume und Geschöpfe des Waldes heilen könnte.
• Sie erforschen die {link:furbolgs}Furbolgs{/link} des Teufelswalds und darüber hinaus und den Wahnsinn, der sie ergriffen hat.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik verzeichnet, wann der Emerald Circle gegründet wurde oder wer ihn zuerst anführte.]=],
		},
	},
})

Translate("deDE", "deadwood-furbolgs", {
	title = "Totenwaldfelle",
	aliases = { "Totenwald", "Stamm der Totenwaldfelle" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Totenwaldfelle sind ein Stamm von {link:furbolgs}Furbolgs{/link} des Teufelswalds, den die {link:fel-magic}Teufelsmagie{/link} in den Wahnsinn getrieben hat. Sie halten das {link:deadwood-village}Lager der Totenwaldfelle{/link} im Süden des Waldes und das {link:felpaw-village}Revier der Teufelspfoten{/link} im Norden, und sie greifen alle an, die sich nähern.]=],
		},
		{
			title = "Der Wahnsinn",
			text = [=[Die {link:timbermaw-furbolgs}Holzschlund{/link} sagen, die Totenwaldfelle seien nicht von Natur aus böse. Es ist die {link:fel-magic}Teufelsmagie{/link}, die ihren Geist vergiftet, und das lässt sich nicht rückgängig machen. Ihre Ritualtotems stinken nach Verfall und Verzweiflung. In ihrem nördlichen Lager brodelt ein grünes, faulendes Gebräu in einem Kessel, und vielleicht trägt es den Wahnsinn zu den Winterfellen von {link:winterspring}Winterspring{/link}.]=],
		},
		{
			title = "Ihre Häuptlinge",
			text = [=[• {b}{link:overlord-ror}Oberherr Ror{/link}{/b} herrscht über das {link:deadwood-village}Lager der Totenwaldfelle{/link} im Süden.
• {b}Häuptling Bloodmaw{/b} herrscht über das Lager nahe der {link:timbermaw-hold}Holzschlundfeste{/link} im Norden.]=],
		},
	},
})

Translate("deDE", "timbermaw-furbolgs", {
	title = "Holzschlund-Furbolgs",
	aliases = { "Holzschlund", "Stamm der Holzschlund" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Holzschlund sind der eine Stamm der {link:furbolgs}Furbolgs{/link}, der der Verderbnis entkommen ist. Sie leben in der {link:timbermaw-hold}Holzschlundfeste{/link}, den Tunneln zwischen dem {link:felwood}Teufelswald{/link} und {link:winterspring}Winterspring{/link}, und sie bewachen sie gegen jeden, der kommt.]=],
		},
		{
			title = "Ein misstrauisches Volk",
			text = [=[Die Holzschlund trauen nur sehr wenigen. Viele Reisende töten heute jeden {link:furbolgs}Furbolg{/link}, den sie sehen, ohne zu fragen, ob er Freund oder Feind ist. Die Holzschlund haben daraus gelernt. Sie heißen nur jene willkommen, die sich gegen die verderbten Stämme bewähren, die {link:deadwood-furbolgs}Totenwaldfelle{/link} des Teufelswalds und die {link:winterfall-furbolgs}Winterfelle{/link} von {link:winterspring}Winterspring{/link}. Es bekümmert sie, gegen ihre eigenen Verwandten zu kämpfen, doch sie tun es. {link:magni-bronzebeard}König Magni{/link} von {link:ironforge}Ironforge{/link} und der Kriegshäuptling der {link:horde}Horde{/link} haben beide in der Vergangenheit versucht, sie zu erreichen.]=],
		},
		{
			title = "Ihre Hoffnung",
			text = [=[Die Holzschlund glauben, dass die {link:winterfall-furbolgs}Winterfelle{/link} von einem Dämon beherrscht werden. Würde er vernichtet, könnte die Heilung der Winterfelle beginnen, und die Feste wäre für viele Jahre sicher.]=],
		},
	},
})

Translate("deDE", "arathandris-silversky", {
