			title = "Zusammenfassung",
			text = [=[Taronn Redfeather vom {link:emerald-circle}Emerald Circle{/link} durchsucht den {link:felwood}Teufelswald{/link} nach einer einzigen reinen Wasserquelle. Er glaubte, die Heilung des Landes wäre weit leichter, wenn er eine fände. Er hoffte, die Krater des Shatter Scar-Tals, wo die Höllenbestien niedergingen, hätten sich mit der Zeit geklärt. Das hatten sie nicht. Er gibt zu, dass die Höllenbestien ihm Angst machen, so hirnlos sie auch sind. Nun will er retten, was er an Geschöpfen des Waldes retten kann, und jene erlösen, die zu verderbt sind, um sie zu retten.]=],
		},
	},
	mentions = {
